    }
  },
  "signal_basis": {
    "component_id": "C050_SIGNAL",
    "value": "Comparative evidence reveals a reliable, diagnostically important conflict with an explanation's necessary prediction, following assessment of evidence reliability and sensitivity to uncertain measurements.",
    "scope": "The conflict must concern an adequately tested necessary prediction within the tested scope. Missing spans cannot establish that a phase was fast.",
